        /* Show toolbar on hover (desktop) or always visible if active/mobile optimization needed */
        .code-widget:hover .code-toolbar, .code-toolbar.visible { opacity: 1; }

        .tool-btn {
            display: inline-flex; items-center; justify-content: center;
