<body>
    <div class="glow-bg glow-green"></div>
    <div class="glow-bg glow-blue"></div>

    <div class="app-shell" id="gesture-zone">
        <!-- Sidebar -->
        <aside id="sidebar">
            <div class="sidebar-header">
                <button class="new-chat-btn" onclick="startNewChat()">
                    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="5" x2="12" y2="19"></line><line x1="5" y1="12" x2="19" y2="12"></line></svg>
                    Új csevegés
                </button>
            </div>
            <div class="history-list" id="history-list"></div>
        </aside>

        <!-- Main Content -->
        <main class="main-container">
            <header>
                <button class="menu-btn" onclick="toggleSidebar()">
                    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="3" y1="12" x2="21" y2="12"></line><line x1="3" y1="6" x2="21" y2="6"></line><line x1="3" y1="18" x2="21" y2="18"></line></svg>
                </button>
                <div id="status-light"></div>
            </header>

            <div class="chat-area" id="chat-area"></div>

            <div class="input-wrapper">
                <div class="input-pill">
                    <textarea id="user-input" placeholder="Ide írhatsz..." rows="1"></textarea>
                    <button class="send-btn" onclick="handleSend()">
                        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="22" y1="2" x2="11" y2="13"></line><polygon points="22 2 15 22 11 13 2 9 22 2"></polygon></svg>
                    </button>
                </div>
            </div>
        </main>
    </div>

    <script>
        let currentThread = [];
        let chatHistory = JSON.parse(localStorage.getItem('chat_history') || '[]');
        let touchStartX = 0;

        // Haptic feedback shim
        function haptic(ms = 10) { if (navigator.vibrate) navigator.vibrate(ms); }

        // Sidebar logic
        function toggleSidebar(forceState) {
            const sb = document.getElementById('sidebar');
            if (forceState === true) sb.classList.add('open');
            else if (forceState === false) sb.classList.remove('open');
            else sb.classList.toggle('open');
            haptic(5);
        }

        // Swipe Gestures
        const gestureZone = document.getElementById('gesture-zone');
        gestureZone.addEventListener('touchstart', e => { touchStartX = e.touches[0].clientX; }, {passive: true});
        gestureZone.addEventListener('touchend', e => {
            const touchEndX = e.changedTouches[0].clientX;
            const diff = touchEndX - touchStartX;

            // Swipe Right to Open (from edge)
            if (touchStartX < 50 && diff > 70) toggleSidebar(true);
            // Swipe Left to Close
            if (diff < -70) toggleSidebar(false);
        }, {passive: true});

        // History Management
        function updateHistoryUI() {
            const list = document.getElementById('history-list');
            list.innerHTML = '';
            chatHistory.slice().reverse().forEach((chat, idx) => {
                const item = document.createElement('div');
                item.className = 'history-item';
                item.innerText = chat.title || 'Névtelen beszélgetés';
                item.onclick = () => loadChat(chatHistory.length - 1 - idx);
                list.appendChild(item);
            });
        }

        function startNewChat() {
            currentThread = [];
            document.getElementById('chat-area').innerHTML = '';
            toggleSidebar(false);
        }

        function loadChat(idx) {
            const chat = chatHistory[idx];
            currentThread = chat.messages;
            document.getElementById('chat-area').innerHTML = '';
            currentThread.forEach(m => renderMessage(m.role, m.content));
            toggleSidebar(false);
        }

        // --- CODE WIDGET ACTIONS ---

        window.copyCode = function(btn) {
            const widget = btn.closest('.code-widget');
            const code = widget.querySelector('code').innerText;
            navigator.clipboard.writeText(code).then(() => {
                const originalHtml = btn.innerHTML;
                btn.innerHTML = `<svg xmlns="" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="var(--neon-green)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg>`;
                setTimeout(() => { btn.innerHTML = originalHtml; }, 2000);
                haptic(15);
            });
        };

        window.toggleWrap = function(btn) {
            const widget = btn.closest('.code-widget');
            const scrollArea = widget.querySelector('.code-scroll-area');
            scrollArea.classList.toggle('wrapped');
            btn.style.color = scrollArea.classList.contains('wrapped') ? 'var(--neon-green)' : 'var(--text-secondary)';
            haptic(10);
        };

        window.runCode = function(btn) {
            // Placeholder for run logic - Visual feedback only
            btn.style.color = 'var(--neon-green)';
            setTimeout(() => { btn.style.color = 'var(--text-secondary)'; }, 500);
            haptic(20);
        };

        // --- RENDERING ENGINE ---

        function renderMessage(role, content) {
            const div = document.createElement('div');
            div.className = `message ${role}`;

            const bubble = document.createElement('div');
            bubble.className = 'message-content';

            // 1. Parse Markdown
            let htmlContent = marked.parse(content);

            // 2. Wrap the HTML in a temp container to manipulate DOM
            const tempDiv = document.createElement('div');
            tempDiv.innerHTML = htmlContent;

            // 3. Transform <pre><code> blocks into Widgets
            tempDiv.querySelectorAll('pre code').forEach(codeBlock => {
                const pre = codeBlock.parentElement;

                // Detect language
                const langClass = [...codeBlock.classList].find(c => c.startsWith('language-'));
                const lang = langClass ? langClass.replace('language-', '') : 'text';

                // Create the Widget Structure
                const widget = document.createElement('div');
                widget.className = 'code-widget';

                // Lucide Icons (Inline SVGs for single-file reliability)
                const iconExpand = `<svg xmlns="" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m7 15 5 5 5-5"/><path d="m7 9 5-5 5 5"/></svg>`;
                const iconWrap = `<svg xmlns="" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="3" x2="21" y1="6" y2="6"/><path d="M3 12h15a3 3 0 1 1 0 6h-4"/><polyline points="16 16 14 18 16 20"/><line x1="3" x2="10" y1="18" y2="18"/></svg>`;
                const iconPlay = `<svg xmlns="" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="6 3 20 12 6 21 6 3"/></svg>`;
                const iconCopy = `<svg xmlns="" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect width="14" height="14" x="8" y="8" rx="2" ry="2"/><path d="M4 16c-1.1 0-2-.9-2-2V4c0-1.1.9-2 2-2h10c1.1 0 2 .9 2 2"/></svg>`;

                widget.innerHTML = `
                    <div class="code-header">
                        <span style="color: ${lang === 'python' ? '#4B8BBE' : '#e0e0e0'}">${lang.toUpperCase()}</span>
                    </div>
                    <div class="code-toolbar">
                        <button class="tool-btn" title="Kibővít" onclick="alert('Kibővítés...')">${iconExpand}</button>
                        <button class="tool-btn" title="Tördelés" onclick="toggleWrap(this)">${iconWrap}</button>
                        <button class="tool-btn" title="Futtatás" onclick="runCode(this)">${iconPlay}</button>
                        <button class="tool-btn" title="Másolás" onclick="copyCode(this)">
                            ${iconCopy}
                        </button>
                    </div>
                    <div class="code-scroll-area">
                        <pre class="${pre.className}"><code class="${codeBlock.className}">${codeBlock.innerHTML}</code></pre>
                    </div>
                `;

                // Replace original <pre> with Widget
                pre.replaceWith(widget);
            });

            // 4. Highlight Logic
            bubble.innerHTML = tempDiv.innerHTML;
            div.appendChild(bubble);

            const area = document.getElementById('chat-area');
            area.appendChild(div);

            // Trigger Prism
            div.querySelectorAll('pre code').forEach(block => Prism.highlightElement(block));

            area.scrollTop = area.scrollHeight;
        }

        // --- NETWORK & CHAT LOGIC ---

        async function handleSend() {
            const input = document.getElementById('user-input');
            const text = input.value.trim();
            if (!text) return;

            input.value = '';
            input.style.height = 'auto';
            haptic(10);

            renderMessage('user', text);
            currentThread.push({role: 'user', content: text});

            const statusLight = document.getElementById('status-light');
            statusLight.style.background = 'var(--neon-green)';
            statusLight.style.boxShadow = '0 0 10px var(--neon-green)';

            // Placeholder loading Bubble
            const loadingId = 'loading-' + Date.now();
            const loadingDiv = document.createElement('div');
            loadingDiv.className = 'message assistant';
            loadingDiv.id = loadingId;
            loadingDiv.innerHTML = `<div class="message-content" style="color:#666">Generálás...</div>`;
            document.getElementById('chat-area').appendChild(loadingDiv);

            try {
                const response = await fetch('/chat', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({ message: text, history: currentThread.slice(0, -1) })
                });

                const reader = response.body.getReader();
                const decoder = new TextDecoder();
                let fullText = "";

                // Remove loading bubble
                document.getElementById(loadingId).remove();

                // Create live updating message
                const liveMsgDiv = document.createElement('div');
                liveMsgDiv.className = 'message assistant';
                const liveContent = document.createElement('div');
                liveContent.className = 'message-content';
                liveMsgDiv.appendChild(liveContent);
                document.getElementById('chat-area').appendChild(liveMsgDiv);

                while (true) {
                    const {value, done} = await reader.read();
                    if (done) break;

                    const chunk = decoder.decode(value);
                    const lines = chunk.split('\n');

                    for (const line of lines) {
                        if (line.startsWith('data: ')) {
                            const dataStr = line.replace('data: ', '');
                            if (dataStr === '[DONE]') break;
                            try {
                                const data = JSON.parse(dataStr);
                                if (data.type === 'content') {
                                    fullText += data.content;
                                    // Only update inner text to avoid re-rendering heavy DOM constantly during stream
                                    // For production code blocks, we wait until end usually, or basic text update
                                    liveContent.innerText = fullText; 
                                }
                            } catch(e){}
                        }
                    }
                    document.getElementById('chat-area').scrollTop = document.getElementById('chat-area').scrollHeight;
                }

                // Final Render with Markdown & Widgets
                liveMsgDiv.remove(); // Remove plain text version
                renderMessage('assistant', fullText); // Render rich version

                currentThread.push({role: 'assistant', content: fullText});

                // Save Title Logic
                if (currentThread.length === 2) {
                    chatHistory.push({ title: text.substring(0, 30), messages: [...currentThread] });
                } else if (chatHistory.length > 0) {
                    chatHistory[chatHistory.length - 1].messages = [...currentThread];
                }
                localStorage.setItem('chat_history', JSON.stringify(chatHistory));
                updateHistoryUI();

            } catch(e) {
                document.getElementById(loadingId)?.remove();
                renderMessage('assistant', "⚠️ Hiba történt a kommunikációban.");
            } finally {
                statusLight.style.background = '#333';
                statusLight.style.boxShadow = 'none';
            }
        }

        // Auto-resize textarea
        document.getElementById('user-input').addEventListener('input', function() {
            this.style.height = 'auto';
            this.style.height = Math.min(this.scrollHeight, 120) + 'px';
        });

        // Initialize
        updateHistoryUI();
    </script>
</body>
</html>

