@media(max-width:768px){aside{position:absolute;height:100%;transform:translateX(-100%);box-shadow:4px 0 12px rgba(0,0,0,0.5)}aside.open{transform:translateX(0)}.menu-toggle{display:block}.main{width:100%}}
table{border-collapse:collapse;width:100%;margin:8px 0;font-size:12px}
th,td{border:1px solid var(--border);padding:6px;text-align:left}
th{background:var(--panel)}
</style>
</head>
<body>
<div class="app">
<aside id="sidebar">
<div class="sidebar-head">
<button class="btn-new" onclick="newChat()">
<svg width="14" height="14" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 5v14M5 12h14"/></svg>ÚJ BESZÉLGETÉS
</button>
</div>
<div class="history" id="history"></div>
</aside>
<main class="main">
<header>
<button class="menu-toggle" onclick="toggleNav()">
<svg width="20" height="20" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 12h18M3 6h18M3 18h18"/></svg>
</button>
<div class="status" id="status"></div>
</header>
<div class="chat-scroll" id="chat"></div>
<div class="input-area">
<div class="input-box">
<textarea id="prompt" placeholder="Parancs..." rows="1" oninput="resize(this)" onkeydown="if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();send()}"></textarea>
<button class="send-btn" onclick="send()">
<svg width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M22 2L11 13M22 2l-7 20-4-9-9-4 20-7z"/></svg>
</button>
</div>
</div>
</main>
</div>
<script>
let state={chats:JSON.parse(localStorage.getItem('h')||'[]'),curr:[],id:Date.now()};
const $=id=>document.getElementById(id);
const html=t=>t.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
marked.setOptions({highlight:null,breaks:true});

function init(){
renderHist();
if(state.chats.length>0) load(0);
}

function toggleNav(){$('sidebar').classList.toggle('open')}
function resize(e){e.style.height='auto';e.style.height=Math.min(e.scrollHeight,100)+'px'}
function save(){localStorage.setItem('h',JSON.stringify(state.chats));renderHist()}

function renderHist(){
const h=$('history');h.innerHTML='';
state.chats.forEach((c,i)=>{
const d=document.createElement('div');
d.className='hist-item';
d.textContent=c.title||'Névtelen';
d.onclick=()=>{load(i);if(window.innerWidth<768)toggleNav()};
h.appendChild(d);
});
}

function newChat(){state.curr=[];state.id=Date.now();$('chat').innerHTML='';$('sidebar').classList.remove('open')}

function load(i){
state.curr=state.chats[i].msgs;
state.id=state.chats[i].id;
const c=$('chat');c.innerHTML='';
state.curr.forEach(m=>append(m.r,m.c,false));
scrollToBottom();
}

function append(role,content,anim=true){
const div=document.createElement('div');
div.className=`msg ${role}`;
const b=document.createElement('div');
b.className='bubble';
if(role==='ai'){
b.innerHTML=parse(content);
hydrate(b);
}else{
b.textContent=content;
}
div.appendChild(b);
$('chat').appendChild(div);
if(anim)scrollToBottom();
}

function scrollToBottom(){const c=$('chat');c.scrollTop=c.scrollHeight}

function parse(md){
try{
const r=new marked.Renderer();
r.code=(c,l)=>{
const validL=l&&Prism.languages[l]?l:'text';
return `<div class="code-block"><div class="code-head"><span>${validL}</span><div class="code-actions"><button class="code-btn" onclick="copy(this)">MÁSOLÁS</button></div></div><div class="code-content"><pre><code class="language-${validL}">${html(c)}</code></pre></div></div>`;
};
return marked.parse(md,{renderer:r});
}catch(e){return md}
}

function hydrate(el){el.querySelectorAll('pre code').forEach(Prism.highlightElement)}

window.copy=btn=>{
const code=btn.closest('.code-block').querySelector('code').innerText;
navigator.clipboard.writeText(code);
const og=btn.innerText;
btn.innerText='MÁSOLT';
setTimeout(()=>btn.innerText=og,2000);
};

async function send(){
const box=$('prompt');
const txt=box.value.trim();
if(!txt)return;
box.value='';box.style.height='auto';
state.curr.push({r:'user',c:txt});
append('user',txt);
const aiDiv=document.createElement('div');
aiDiv.className='msg ai';
const aiBub=document.createElement('div');
aiBub.className='bubble';
aiDiv.appendChild(aiBub);
$('chat').appendChild(aiDiv);
$('status').classList.add('active');
let full='';
try{
const res=await fetch('/api/chat',{
method:'POST',
headers:{'Content-Type':'application/json'},
body:JSON.stringify({message:txt,history:state.curr.slice(0,-1)})
});
if(!res.ok)throw new Error('API Error');
const reader=res.body.getReader();
const dec=new TextDecoder();
while(true){
const{done,value}=await reader.read();
if(done)break;
const chunk=dec.decode(value,{stream:true});
full+=chunk;
aiBub.innerHTML=parse(full);
scrollToBottom();
}
hydrate(aiBub);
state.curr.push({r:'ai',c:full});
const exIdx=state.chats.findIndex(c=>c.id===state.id);
if(exIdx>-1)state.chats[exIdx]={id:state.id,title:state.chats[exIdx].title,msgs:state.curr};
else state.chats.unshift({id:state.id,title:txt.slice(0,25),msgs:state.curr});
save();
}catch(e){
aiBub.innerHTML=`<span style="color:red">Hálózati hiba: ${e.message}. Ellenőrizd a szervert.</span>`;
}finally{
$('status').classList.remove('active');
}
}
init();
</script>
</body>
</html>
